function tidy(line) {
  const match = /^\[(\w+)\]\s*(.*)$/.exec(line.trim())
  const level = match ? match[1].toLowerCase() : "info"
  const message = (match ? match[2] : line).replace(/\s+/g, " ").trim()
  return `${level}: ${message}`
}
